corrected_code:
const express = require('express');
const { CalendarEvent } = require('../models');
const { userAuth } = require('../auth');

const app = express();
app.use(express.json());

app.post('/api/agent/tools/get-meeting-details', userAuth, async (req, res) => {
  const { eventId } = req.body.toolArgs || {};

  const event = await CalendarEvent.findByPk(eventId);
  if (!event) {
    return res.status(404).json({ error: 'Meeting not found' });
  }

  // Ensure user is an organizer or invited attendee of the meeting
  const isAttendee = event.attendeeEmails?.includes(req.user.email) || event.organizerId === req.user.id;
  if (!isAttendee) {
    return res.status(403).json({ error: 'Access denied: you are not an attendee of this meeting' });
  }

  res.json({
    id: event.id,
    summary: event.summary,
    startTime: event.startTime,
    attendees: event.attendeeEmails
  });
});

app.listen(8115);
